# Let's look at the pattern of non-6 values in input
print("Input non-6 positions (row, col, value):")
for i, row in enumerate(input_grid):
    for j, v in enumerate(row):
        if v != 6:
            print(f"  ({i}, {j}): {v}")

print("\nInput non-6 values in reading order:")
for i, row in enumerate(input_grid):
    for j, v in enumerate(row):
        if v != 6:
            print(v, end=" ")
    print()

# Find which output rows make up the 6 unique rows
output_unique = {}
for i, row in enumerate(output_grid):
    key = tuple(row)
    if key not in output_unique:
        output_unique[key] = i

print("Output unique rows and their first occurrence:")
for key, first_occurrence in sorted(output_unique.items(), key=lambda x: x[1]):
    print(f"  First seen at row {first_occurrence}: ")
    print(f"    {to_string(row=first_unique[key])[:80]}...")

# Let's store this for comparison
first_unique = {val: k for k, v in output_unique.items()}

# Find which output rows make up the 6 unique rows
output_unique = {}
for i, row in enumerate(output_grid):
    key = tuple(row)
    if key not in output_unique:
        output_unique[key] = i

print("Number of unique output rows:", len(output_unique))

# Let's list them with indices
first_unique_rows = [output_unique[k] for k in output_unique]
print("Rows that first appear:", sorted(first_unique_rows))

# For each unique output row, let's see what it looks like
for key in sorted(output_unique.items()):
    first_occ = key[1]
    row_str = ' '.join(map(str, key[0]))
    print(f"Row {first_occ}: {row_str[:60]}..." if len(row_str) > 60 else f"Row {first_occ}: {row_str}")

# Now let's check if these might relate to input rows in some mirrored way
# Input row 0 has 8 at position 6, output row 5 (last of first 6) has ...
print("\n\\nInput row 5 non-6 positions:")
for j, v in enumerate(input_grid[5]):
    if v != 6:
        print(f"  col {j}: {v}")

print("Output row 5 non-6 positions:")
for j, v in enumerate(output_grid[5]):
    if v != 6:
        print(f"  col {j}: {v}")

# Check where 9 appears in input and output
print("9 positions in input:")
for i, row in enumerate(input_grid):
    for j, v in enumerate(row):
        if v == 9:
            print(f"  ({i}, {j})")

print("\n9 positions in output:")
for i, row in enumerate(output_grid):
    for j, v in enumerate(row):
        if v == 9:
            print(f"  ({i}, {j})")

# Also let's look at where specifically there are 9s in the output
print("\nRow by row 9 positions:")
for i, row in enumerate(output_grid):
    nine_cols = [j for j, v in enumerate(row) if v == 9]
    if nine_cols:
        print(f"  Row {i}: cols {nine_cols}")

# Let me trace exactly where 9s are in Block 1 (rows 0-5)
print("9 positions in Block 1 (output rows 0-5):")
for i, row in enumerate(output_grid[:6]):
    nine_cols = [j for j, v in enumerate(row) if v == 9]
    if nine_cols:
        print(f"  Block 1 Row {i} (output row {i}): cols {nine_cols}")

# Now let me look at the same rows but with rows from Block 1
print("\nBlock 1 rows with all their 9s:")
block1 = output_grid[:6]
for i, row in enumerate(block1):
    nine_cols = [j for j, v in enumerate(row) if v == 9]
    if nine_cols or any(v != 6 for v in row):
        print(f"  [{i}]: {row}")
